			'"tables_json" TEXT NOT NULL,',
			'"schema_json" TEXT NOT NULL,',
			'"checksum" TEXT NOT NULL,',
			'"sql_text" TEXT NOT NULL,',
			'"updated_at_ms" INTEGER NOT NULL',
